// Tests for the browser-side findings core. The golden file is generated by
// the Python findings view, so the two stay in step.
// Run: node --test 'tools/mod-view/test_*.mjs'
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const here = path.dirname(fileURLToPath(import.meta.url));
const M = createRequire(import.meta.url)('./model.js');
const data = (n) => readFileSync(path.join(here, 'testdata', n), 'utf8');
const records = data('sample-run.jsonl').split('\n').filter(Boolean).map((l) => JSON.parse(l));
const profile = JSON.parse(data('profile.json'));
const expected = JSON.parse(data('expected-findings.json'));
const PKG = 'com.example.sample';

// Drop firstTs; keep key/count/errors, the shape the Python side is compared in.
function strip(f) {
  const sections = {};
  for (const [s, lst] of Object.entries(f.sections)) {
    sections[s] = lst.map((x) => ({ key: x.key, count: x.count, errors: x.errors }));
  }
  return { sections, hidden: f.hidden, coverage: f.coverage };
}

test('findings match the Python golden file', () => {
  const f = M.findings(records, profile, PKG);
  assert.deepEqual(strip(f), expected);
  assert.equal(f.sections.net[0].count, 16);
  assert.deepEqual(f.hidden.binder, { records: 1, keys: 1 });
});

test('sections come out in order of first appearance, firstTs is the record ts', () => {
  const f = M.findings(records, profile, PKG);
  assert.deepEqual(Object.keys(f.sections), Object.keys(expected.sections));
  assert.equal(f.sections.dexload[0].firstTs, records.find((r) => r.type === 'dexload_detect').ts_ns);
});

test('inferPackage reads the perm-watch package', () => {
  assert.equal(M.inferPackage(records), PKG);
  assert.equal(M.inferPackage([{ type: 'net' }]), null);
  assert.equal(M.findings(records, profile).sections.net[0].count, 16);
});

test('norm and recordKey agree with Python on tricky inputs', () => {
  assert.equal(M.norm('/proc/1234/task/99/x', null), '/proc/<pid>/task/<tid>/x');
  assert.equal(M.norm('port 3434 id 1795508465039', null), 'port 3434 id <n>');
  assert.equal(M.norm('/data/data/com.a.b/x 0xdeadbeef', 'com.a.b'), '/data/data/<pkg>/x <hex>');
  assert.equal(M.norm('/data/app/~~abc==/com.a.b-xyz==/base.apk', null), '/data/app/<install>/base.apk');
  assert.equal(M.norm(null, null), '');
  assert.equal(M.recordKey({ type: 'net', event: 'close' }, null), null);
  assert.deepEqual(M.recordKey({ type: 'brand_new', x: 1 }, null), ['brand_new', 'brand_new']);
  assert.deepEqual(M.recordKey({ type: 'binder_api', interface: 'I', code: 5 }, null), ['binder', 'I.#5']);
  assert.equal(M.recordKey({ type: 'coverage' }, null), null);
  assert.equal(M.recordKey({ type: 'x_summary' }, null), null);
  assert.equal(M.recordKey({ type: 'perm_change', change: 'baseline' }, null), null);
  assert.equal(M.recordKey({ type: 'file_access', categories: ['own_app_dir'] }, null), null);
  assert.deepEqual(M.recordKey({ type: 'execve', argv: [], filename: '/system/bin/sh' }, null), ['exec', 'sh']);
  assert.deepEqual(M.recordKey({ type: 'prop_read' }, null), ['prop', 'None']);
});

test('coverage degraded engines are listed, exempt ones are not', () => {
  const f = M.findings([
    { type: 'coverage', engine: 'a', clean: false },
    { type: 'coverage', engine: 'b', clean: false, exempt: true },
    { type: 'coverage', engine: 'c', clean: true },
  ], { keys: {} }, null);
  assert.deepEqual(f.coverage, { records: 3, degraded: ['a'] });
});

// ---- attribution and step building ----
const marks = M.parseMarks(data('sample-run.marks'));
const noMarks = data('no-marks.jsonl').split('\n').filter(Boolean).map((l) => JSON.parse(l));
const T0 = records[0].ts_ns;
const netOpens = records.filter((r) => r.type === 'net' && r.event === 'open');
const netOpenTimes = netOpens.map((r) => r.ts_ns);
const netOpenAt = (sec) => ({
  type: 'net', pid: 1, ts_ns: T0 + sec * 1e9, event: 'open', proto: 'tcp',
  dest: '203.0.113.9:80', host: '203.0.113.9:80', host_source: 'http',
});

test('parseMarks reads lab marks and ignores blank or bad lines', () => {
  assert.equal(marks.length, 6);
  assert.equal(marks[0].label, 'launch');
  assert.equal(marks[0].ts, T0);
  assert.deepEqual(M.parseMarks('\nnot json\n{"label":"x"}\n{"ts_ns":5,"label":"y"}\n'), [{ ts: 5, label: 'y' }]);
});

test('labCaused covers begin..end plus 2 s, and nothing else', () => {
  const at = (s) => ({ type: 'perm_change', ts_ns: T0 + s * 1e9 });
  assert.equal(M.labCaused(at(48.3), marks), true);
  assert.equal(M.labCaused(at(50.4), marks), true);   // end 48.4 + 2
  assert.equal(M.labCaused(at(48.1), marks), false);
  assert.equal(M.labCaused(at(60), marks), false);
  assert.equal(M.labCaused(at(48.3), []), false);
  // a begin with no matching end is not a window
  assert.equal(M.labCaused(at(48.3), [{ ts: T0 + 48.2e9, label: 'grant-begin:x' }]), false);
});

test('lab grants go to the lab, never the sample', () => {
  const s = M.buildSteps(records, marks, profile, PKG);
  const lab = s.filter((x) => x.template === 'lab_grant');
  assert.equal(lab.length, 1); assert.equal(lab[0].actor, 'lab');
  assert.ok(!s.some((x) => x.actor === 'sample' && x.recs.some((r) => r.type === 'perm_change' && r.change !== 'baseline')));
});

test('lab grant windows 10 s or more apart stay separate steps', () => {
  const m2 = [
    { ts: T0 + 48.2e9, label: 'grant-begin:a' }, { ts: T0 + 48.4e9, label: 'grant-end:a' },
    { ts: T0 + 60.0e9, label: 'grant-begin:b' }, { ts: T0 + 61.0e9, label: 'grant-end:b' },
  ];
  const recs = [
    { type: 'perm_change', ts_ns: T0 + 48.3e9, package: PKG, category: 'appop', name: 'X', change: 'changed', new: 'allow' },
    { type: 'perm_change', ts_ns: T0 + 60.5e9, package: PKG, category: 'appop', name: 'Y', change: 'changed', new: 'allow' },
  ];
  assert.equal(M.buildSteps(recs, m2, { keys: {} }, PKG).filter((x) => x.template === 'lab_grant').length, 2);
});

test('without marks, permission changes are unattributed', () => {
  const s = M.buildSteps(noMarks, [], profile, PKG);
  assert.ok(s.every((x) => x.template !== 'lab_grant'));
  assert.ok(s.some((x) => x.template === 'perm_unattributed' && x.actor === 'unattributed'));
  assert.ok(s.every((x) => x.template !== 'detonation'));
});

test('persistence is ordered by its first evidence, not its respawns', () => {
  const ids = M.buildSteps(records, marks, profile, PKG).map((x) => x.template);
  assert.deepEqual(ids, ['detonation', 'payload_packed', 'persistence', 'c2_beacon', 'lab_grant', 'a11y_abuse']);
});

test('step shape and data for the sample run', () => {
  const s = M.buildSteps(records, marks, profile, PKG);
  const by = (t) => s.find((x) => x.template === t);
  assert.equal(by('detonation').actor, 'lab');
  assert.equal(by('detonation').firstTs, T0);
  assert.equal(by('payload_packed').actor, 'sample');
  assert.equal(by('payload_packed').data.ino, 38531);
  assert.equal(by('payload_packed').data.size, 777276);
  assert.equal(by('payload_packed').recs.length, 2);
  assert.equal(by('persistence').data.respawns, 12);
  assert.equal(by('c2_beacon').data.count, 16);
  assert.equal(Math.round(by('c2_beacon').data.beacon.intervalS), 20);
  assert.equal(by('a11y_abuse').recs.length, 2);
  s.forEach((x) => assert.ok(x.recs.every((r) => typeof r === 'object')));
});

test('beacon window names only the regular part', () => {
  const w = M.beaconWindow(netOpenTimes);
  assert.equal(Math.round(w.intervalS), 20);
  assert.ok(w.fromTs > netOpenTimes[8]);
  assert.equal(w.fromTs, netOpenTimes[10]);
  assert.equal(w.toTs, netOpenTimes[15]);
  assert.equal(M.beaconWindow([0, 20e9, 40e9, 60e9]), null);     // only 3 gaps
  assert.equal(M.beaconWindow([]), null);
});

test('respawns counted from exits followed by a new pid', () => {
  assert.equal(M.respawns(records), 12);
  assert.equal(M.respawns([{ type: 'proc_exit', pid: 1, ts_ns: 1 }, { type: 'binder_api', pid: 1, ts_ns: 2 }]), 0);
  assert.equal(M.respawns([{ type: 'binder_api', pid: 2, ts_ns: 3 }, { type: 'binder_api', pid: 1, ts_ns: 1 }, { type: 'proc_exit', pid: 1, ts_ns: 2 }]), 1);
});

test('packed vs downloaded: a net open just before the drop means downloaded', () => {
  const kinds = (rs) => M.buildSteps(rs, marks, profile, PKG).map((x) => x.template);
  assert.ok(kinds([netOpenAt(-30), ...records]).includes('payload_downloaded'));
  assert.ok(!kinds([netOpenAt(-30), ...records]).includes('payload_packed'));
  assert.ok(kinds([netOpenAt(-130), ...records]).includes('payload_packed'));
  assert.ok(kinds(records).includes('payload_packed'));
});

test('memload is its own step; record strings like __proto__ do not misbehave', () => {
  const rs = [
    { type: 'dexload_detect', pid: 1, ts_ns: 5, stage: 'memload', kind: 'dex', path: null, ino: 0 },
    { type: 'dexload_detect', pid: 1, ts_ns: 6, stage: 'memload', kind: 'dex', path: null, ino: 0 },
    { type: 'file_access', pid: 1, ts_ns: 7, path: '__proto__', categories: [] },
    { type: 'net', pid: 1, ts_ns: 8, event: 'open', proto: 'tcp', host: '__proto__' },
  ];
  const s = M.buildSteps(rs, [], { keys: {} }, null);
  assert.equal(s.filter((x) => x.template === 'payload_memload').length, 2);
  assert.ok(s.some((x) => x.template === 'file_probe'));
  assert.ok(s.some((x) => x.template === 'net_contact'));
});
